CREATE TABLE IF NOT EXISTS migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE price_versions(id uuid PRIMARY KEY, name text NOT NULL, status text NOT NULL CHECK(status IN ('draft','published')), prices jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE TABLE rules_versions(id uuid PRIMARY KEY, title text NOT NULL, body text NOT NULL, status text NOT NULL CHECK(status IN ('draft','published')), created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE TABLE teams(id uuid PRIMARY KEY, name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 80), name_key text NOT NULL UNIQUE, players jsonb NOT NULL DEFAULT '[]', archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deck_versions(id uuid PRIMARY KEY, team_id uuid NOT NULL REFERENCES teams(id), slot integer NOT NULL CHECK(slot IN (1,2)), source_url text, source_text text, deck jsonb NOT NULL, score jsonb NOT NULL, price_version_id uuid NOT NULL REFERENCES price_versions(id), actor text NOT NULL, restored_from uuid REFERENCES deck_versions(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX deck_team_history ON deck_versions(team_id,slot,created_at DESC);
CREATE TABLE events(id uuid PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', starts_at timestamptz NOT NULL, timezone text NOT NULL DEFAULT 'America/Phoenix', location text NOT NULL DEFAULT 'Online', registration_opens timestamptz, registration_closes timestamptz, lock_at timestamptz, locked boolean NOT NULL DEFAULT false, status text NOT NULL CHECK(status IN ('scheduled','registration','running','complete','cancelled')), price_version_id uuid NOT NULL REFERENCES price_versions(id), price_snapshot jsonb NOT NULL, provider text NOT NULL DEFAULT 'challonge' CHECK(provider IN ('challonge','mock')), tournament_id text, tournament_url text, tournament_type text NOT NULL DEFAULT 'single elimination', tournament_state text, sync_data jsonb NOT NULL DEFAULT '{}', synced_at timestamptz, sync_error text, champion text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE registrations(id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id), team_id uuid NOT NULL REFERENCES teams(id), team_name text NOT NULL, participant_id text, decks jsonb NOT NULL DEFAULT '[]', score jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,team_id), UNIQUE(event_id,participant_id));
CREATE TABLE registration_versions(id uuid PRIMARY KEY, registration_id uuid NOT NULL REFERENCES registrations(id), decks jsonb NOT NULL, score jsonb, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts(ip_hash text PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, resets_at timestamptz NOT NULL);
CREATE TABLE audit_log(id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, entity_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mock_tournaments(id text PRIMARY KEY, state jsonb NOT NULL);
INSERT INTO migrations(version) VALUES(1);
